// @ts-nocheck
import * as React from "react"
import { cn } from "@/lib/utils"

export interface CheckboxProps {
  state?: "Default" | "Disabled" | "Selected" | "Error";
  size?: "Large" | "Small";
  className?: string;
  children?: React.ReactNode
}

const Checkbox = React.forwardRef<HTMLDivElement, CheckboxProps>(
  ({ className, children, ...props }, ref) => {
    return (
      <div
        ref={ref}
        className={cn("inline-flex items-center justify-center rounded w-[341px] h-[116px]", className)}
        {...props}
      >
        {children}
      </div>
    )
  }
)
Checkbox.displayName = "Checkbox"

export { Checkbox }
export default Checkbox

// @ts-nocheck
import * as React from "react"

export interface ControlProps {
  state?: "Default" | "Disabled"
  size?: "Small" | "Large"
  className?: string
  children?: React.ReactNode
  onClick?: () => void
}

const Control = React.forwardRef<HTMLDivElement, ControlProps>(
  ({ state = "Default", size = "Small", className, children, ...props }, ref) => {
    return (
      <div
      ref={ref}
      className={className}
      style={{ display: "inline-flex", alignItems: "center", gap: "8px", padding: "8px 12px", borderRadius: "5px", background: "#e8e8e8", border: "1px solid #e4e4e7", fontFamily: "system-ui", fontSize: "14px", color: "#18181b" }}
      {...props}
    >
      {children ?? "Control"}
    </div>
    )
  }
)
Control.displayName = "Control"

export { Control }
export default Control

// @ts-nocheck
import * as React from "react"

export interface AccordionProps {
  title?: string
  defaultOpen?: boolean
  className?: string
  children?: React.ReactNode
}

const Accordion = React.forwardRef<HTMLDivElement, AccordionProps>(
  ({ defaultOpen = false, title = "Accordion", className, children, title, ...props }, ref) => {
    const [open, setOpen] = React.useState(defaultOpen)
    return (
      <div ref={ref} className={className} style={{ border: "1px solid #e4e4e7", borderRadius: "5px", overflow: "hidden", fontFamily: "Avenir Next LT Pro" }} {...props}>
      <button onClick={() => setOpen(!open)} style={{ width: "100%", padding: "14px 16px", display: "flex", alignItems: "center", justifyContent: "space-between", cursor: "pointer", border: "none", background: "#fff", textAlign: "left" }}>
        <span style={{ fontSize: "16px", fontWeight: 500, color: "#18181b" }}>{title}</span>
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#71717a" strokeWidth="2" style={{ transform: open ? "rotate(180deg)" : "none", transition: "transform 0.2s" }}><path d="M6 9l6 6 6-6"/></svg>
      </button>
      {open && <div style={{ padding: "12px 16px", background: "#fafafa", borderTop: "1px solid #e4e4e7", fontSize: "13px", color: "#71717a", lineHeight: 1.5 }}>{children}</div>}
    </div>
    )
  }
)
Accordion.displayName = "Accordion"

export { Accordion }
export default Accordion

